from pathlib import Path
from datetime import date, datetime, timedelta
import re

logs_dir = Path('/app/logs')
out_path = Path('/app/summary.csv')
ref = date(2025, 8, 12)

periods = {
    'today': (ref, ref),
    'last_7_days': (ref - timedelta(days=6), ref),
    'last_30_days': (ref - timedelta(days=29), ref),
    'month_to_date': (ref.replace(day=1), ref),
}
severities = ['ERROR', 'WARNING', 'INFO']

counts = {p: {s: 0 for s in severities} for p in periods}
counts['total'] = {s: 0 for s in severities}

pat = re.compile(r'\b(ERROR|WARNING|INFO)\b')

for fp in sorted(logs_dir.glob('*.log')):
    name = fp.name
    dstr = name.split('_', 1)[0]
    fdate = datetime.strptime(dstr, '%Y-%m-%d').date()

    local = {s: 0 for s in severities}
    with fp.open('r', encoding='utf-8', errors='ignore') as f:
        for line in f:
            m = pat.search(line)
            if m:
                local[m.group(1)] += 1

    for s in severities:
        counts['total'][s] += local[s]

    for pname, (start, end) in periods.items():
        if start <= fdate <= end:
            for s in severities:
                counts[pname][s] += local[s]

rows = ['period,severity,count']
for pname in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
    for s in severities:
        rows.append(f'{pname},{s},{counts[pname][s]}')

out_path.write_text('\n'.join(rows) + '\n', encoding='utf-8')
print(out_path)
